 "content": "def transform(grid):
    g = [row[:] for row in grid]
    colors = {v for row in g for v in row if v not in (0, 1)}
    # The marked object is the color other than the binary background colors.
    marker = next(iter(colors))
    points = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == marker]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = {(r-r0, c-c0) for r, c in points}
    h = max(r for r, c in shape) + 1
    w = max(c for r, c in shape) + 1
    H, W = len(g), len(g[0])
    for r in range(H-h+1):
        for c in range(W-w+1):
            if all(g[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    g[r+dr][c+dc] = marker
    return g
